--- 请求剩余的免费次数
function UIFightTeamSweepBtnGroup:RequestFreeTimes()
    if SkipRequest then
        self.freeTimesRemain = 5
    else
        GameUtils.Request(Interfaces.OverseaRegionalSweepFreeTimes, {}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                return
            end
            local jsonData = response.data
            self.freeTimesRemain = math.max(checkNumber(jsonData.totalNum - jsonData.useNum), 0) 
            self:Show()
        end)
    end
end

--- 初始化组件
function UIFightTeamSweepBtnGroup:InitComponent()
    local LB_SweepTimesDesc = self.LB_SweepTimesDesc
    if isNull(LB_SweepTimesDesc.Env) then
        LB_SweepTimesDesc:Init()
    end
    self.LT_SweepTimesDesc = LB_SweepTimesDesc.Env

    local LB_ConsumePop = self.LB_ConsumePop
    if isNull(LB_ConsumePop.Env) then
        LB_ConsumePop:Init()
    end
    self.LT_ConsumePop = LB_ConsumePop.Env

    SetButtonAction(self.Btn_Sweep, Bind(self, self.OnSweepClicked))

    self.inited = true
end

--- 显示界面
function UIFightTeamSweepBtnGroup:Show()
    if isNull(self.controller) then
        return
    end
    
    if not self.inited then
        self:InitComponent()
    end

    -- 设置按钮状态
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self.questId)
    if not isPass then
        local fontStyleBtn = self.Btn_Sweep:GetComponent(typeof(FontStyleButton))
        fontStyleBtn:ResetFontStyle("B18")
    end
    
    -- 设置免费次数文本
    local showFreeTimes = true
    if self.questType == Constants.IDType.QuestRegion then
        local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.questId)
        if checkNumber(questVo.levelType) == 2 then
            showFreeTimes = false
        end
    end
    if showFreeTimes then
        local playerDojo = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent).playerDojo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4032, "WelfareSettingVo", 1)

        local normalFreeTimes = checkInt(CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 23).num)
        local vipFreeTimes = checkInt(GameUtils.GetPrivilegeCardAddNumByName(tonumber(vo.giftId), "autoNum")) or 10

        self.LT_SweepTimesDesc:SetFreeTimesDesc(self.freeTimesRemain, normalFreeTimes + vipFreeTimes)
    else
        KTool.SetActive(self.LT_SweepTimesDesc.controller.gameObject, false)
    end

    -- 设置消耗道具提示
    ---@type BackpackComponent
    local backpack = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    local sweepTicketNum = backpack:GetGoodsNo(SweepTicketId)

    if self.freeTimesRemain > 0 or not showFreeTimes then
        CfUtils.FillCommonBtnConsumePopNode(self.LB_ConsumePop, self.consumeId, self.consumeNum)
    else
        local extraConsume = {goodsId = SweepTicketId, consumeNum = SweepTicketConsumeNum}
        CfUtils.FillCommonBtnConsumePopNode(self.LB_ConsumePop, self.consumeId, self.consumeNum, nil, nil, extraConsume)
    end
end

--- 扫荡
function UIFightTeamSweepBtnGroup:OnSweepClicked()
    local isPass = QuestConfMgr:GetInstance():IsPassQuest(self.questId)
    if not isPass then
        GameUtils.Toast(localize("首次通关后解锁扫荡"))
        return
    end
    local isFilled, packetVo = GoodsUtils.IsPacketFilled()
    if isFilled then
        GameUtils.Toast(localize("_name_背包已满，请前往清理", {_name_ = packetVo.name}))
        return
    end
    -- 保存编队
    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    teamComponent:SetTeamReq(self.questId, function()
    
        -- 选择接口
        local interface = ""
        if self.questType == Constants.IDType.QuestDaily then
            interface = Interfaces.OverseaRegionalDailySweep
        elseif self.questType == Constants.IDType.QuestRegion then
            interface = Interfaces.OverseaRegionalSweep
        end
        
        -- 请求扫荡结果
        local succeed = false
        local operation = GameUtils.Request(interface, {questId = self.questId}, function(request, response)
            if checkNumber(response.errCode) ~= 0 then
                if checkNumber(response.errCode) == CodeLackHP then
                    -- 体力跳转
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIHPDialog })
                elseif checkNumber(response.errCode) == CodeLackTicket then
                    -- 扫荡券跳转
                    GoodsUtils.ShowCommonLackMaterialDialog({{ goodsId = SweepTicketId, num = SweepTicketConsumeNum }})
                elseif checkNumber(response.errCode) == CodeLackSpecialTicket then
                    -- 特殊券跳转
                    UIModule.OpenDialog({ id = Constants.UITypeIds.StoreDiamondExchangeDialog, 
                        parameters = {id = Constants.Currency.SPTicketExchangeId, callback = Bind(self, self.Refresh)}})
                elseif checkNumber(response.errCode) == CodeNotThrough then
                    GameUtils.Toast(localize("未通关的关卡无法扫荡"))
                end
                return
            end
            succeed = true
            local jsonData = response.data
            local hp = jsonData.hp
            local rewards = jsonData.rewards
            local extraRewards = jsonData.extraRewards
            local playerLv = jsonData.playerLv
            local mainExp = jsonData.mainExp
            local cardExp = jsonData.cardExp
            local energyPoint = jsonData.energyPoint
            local taskInfo = jsonData.questGradeTaskProgress
            local regionalBossData = jsonData.regionalBossData

            -- 为防未来有一次请求扫荡多次的情况，服务器加了一个次数的字典
            if not IsNull(rewards) and not IsNull(rewards["1"]) then
                jsonData.rewards = rewards["1"]
            end
            if not IsNull(extraRewards) and not IsNull(extraRewards["1"]) then
                jsonData.extraRewards = extraRewards["1"]
            end

            -- print("[扫荡] response", table.dump(jsonData, nil, 5))

            local Mgr = FightPreWarMgr:GetInstance()
            local params = {}
            params.questId = self.questId

            -- 更新能量点儿
            if not isNull(energyPoint) then
                local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
                comp:UpdateNewDailyQuestID(self.questId, energyPoint)  -- 更新最近关卡
            end

            -- 更新玩家经验
            local playerOldLv, playerOldExp = Mgr:UpdatePlayerExp(jsonData)
            params.playerExpInfo = {
                newLv = jsonData.playerLv,
                oldLv = playerOldLv,
                newExp = jsonData.mainExp,
                oldExp = playerOldExp,
            }
            -- 更新卡牌经验
            params.cardExpInfo = Mgr:UpdateCardExp(jsonData)
            
            -- 更新玩家奖励和体力
            Mgr:UpdateRewards(jsonData)

            -- 特殊材料副本，消耗特殊券
            if self.consumeId == ActionUtils.GetDailyQuestTicketId() then
                local comp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.DailyQuestComponent)
                comp:ConsumeTicket()
            end

            local costSweepTicket = true
            if self.questType == Constants.IDType.QuestRegion then
                local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.questId)
                if checkNumber(questVo.levelType) == 2 then
                    costSweepTicket = false
                end
            end
            -- 更新扫荡券
            if self.freeTimesRemain <= 0 and costSweepTicket then
                GoodsUtils.DrawRewards({ {goodsId = SweepTicketId, num = -SweepTicketConsumeNum} })
            end

            -- 构造奖励和任务数据
            params.loopViewListData = self:MakeLoopViewListData(jsonData)
            params.extraRewards = jsonData.extraRewards

            -- 记录歼灭战数据和是否触发
            if not IsNull(regionalBossData) then
                params.needShowAnnihilationPopup = Mgr:NeedShowAnnihilationPopup(self.questId, regionalBossData)
                params.regionalBossData = regionalBossData
                -- print("[扫荡] 歼灭战进度", regionalBossData.progress)
                local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActionComponent)
                comp:UpdateReginQuestInfo(self.questId, regionalBossData)
            end

            UIModule.OpenDialog({id = Constants.UITypeIds.UIFightTeamSweepRewardDialog, parameters = params})

            -- 刷新编队里面的角色信息
            Events.Broadcast(Constants.EventNames.RefeshTeamMember, nil)

            -- self:Refresh()
        end, nil, nil, nil, nil, true)
    
    end)
end

--- 构造奖励和任务数据
function UIFightTeamSweepBtnGroup:MakeLoopViewListData(jsonData)
    local data = {}
    -- 构造奖励数据
    data[1] = self:GetRewards(jsonData)

    if not IsNull(jsonData.questGradeTaskProgress) and table.count(jsonData.questGradeTaskProgress) > 0 then
        -- 构造任务标题（空数据）
        data[2] = {}
        -- 构造任务数据
        for taskId, taskInfo in pairs(jsonData.questGradeTaskProgress) do
            table.insert(data, taskInfo)
        end
    end
    return data
end

--- 从奖励列表里移除固定奖励
---@param jsonData any
function UIFightTeamSweepBtnGroup:GetRewards(jsonData)
    local rewards = clone(jsonData.rewards)
    local needRemove = {}
    local extraRewards = jsonData.extraRewards
    for i, extraReward in ipairs(extraRewards) do
        for j, reward in ipairs(rewards) do
            if reward.goodsId == extraReward.goodsId then
                reward.num = reward.num - extraReward.num
                if reward.num <= 0 then
                    table.insert(needRemove, j)
                end
            end
        end
    end
    for i, index in ipairs(needRemove) do
        table.remove(rewards, index)
    end
    print("[扫荡]", table.dump(rewards,nil,3))
    return rewards
end

return UIFightTeamSweepBtnGroup